    /* ------------------------------------------------------------------ */
    /* 3. Main entry point – orchestrates the test                         */
    /* ------------------------------------------------------------------ */
    public void runTest() throws Exception {
        // 3.1 Load the JSON test case
        String testcaseData = loadTestCase("humongous-test-case.json");

        // 3.2 Define the GC trigger – a simple Runnable that calls System.gc()
        Runnable doGC = () -> System.gc();

        // 3.3 Prepare the checker – a Consumer that forwards to referenceChecker()
