        List<String> shouldNotContain = Collections.singletonList("OutOfMemoryError");

        // 3.6 Call the helper
        functions.TestObjectGraphAfterGC_doTesting.doTesting(
                testcaseData,
                doGC,
                checker,
                gcLogName,
                shouldContain,
                shouldNotContain
