    }

    /* ------------------------------------------------------------------ */
    /* 4. Helper to analyse the log after the test                        */
    /* ------------------------------------------------------------------ */
    private void analyseLog(String logPath) throws Exception {
        String logContent = new String(Files.readAllBytes(Paths.get(logPath)), StandardCharsets.UTF_8);

        if (!logContent.contains("GC pause")) {
            throw new AssertionError("'GC pause' not found in log");
        }
        if (logContent.contains("OutOfMemoryError")) {
            throw new AssertionError("'OutOfMemoryError' unexpectedly found in log");
        }

        System.out.println("Log analysis passed: 'GC pause' present, 'OutOfMemoryError' absent.");
    }

